namespace SupplierDirectory.Infrastructure;
public interface IFileStorageService { Task<string> SaveImageAsync(IFormFile file, string folder, CancellationToken ct); Task DeleteAsync(string? relativePath); }
public sealed class LocalFileStorageService(IWebHostEnvironment environment, IConfiguration config) : IFileStorageService {
 public async Task<string> SaveImageAsync(IFormFile file,string folder,CancellationToken ct) { var max=config.GetValue<long>("Upload:MaxImageBytes",5242880); var allowed=new[]{".jpg",".jpeg",".png",".webp"}; var ext=Path.GetExtension(file.FileName).ToLowerInvariant(); if(file.Length==0||file.Length>max||!allowed.Contains(ext)||!file.ContentType.StartsWith("image/",StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException("ملف الصورة غير صالح أو يتجاوز الحجم المسموح"); var root=Path.Combine(environment.WebRootPath,config["Upload:Root"]??"uploads",folder); Directory.CreateDirectory(root); var name=$"{Guid.NewGuid():N}{ext}"; await using var output=File.Create(Path.Combine(root,name)); await file.CopyToAsync(output,ct); return $"/{config["Upload:Root"]??"uploads"}/{folder.Replace('\\','/')}/{name}"; }
 public Task DeleteAsync(string? path) { if(!string.IsNullOrWhiteSpace(path)) { var clean=path.TrimStart('/').Replace('/',Path.DirectorySeparatorChar); var target=Path.GetFullPath(Path.Combine(environment.WebRootPath,clean)); if(target.StartsWith(Path.GetFullPath(environment.WebRootPath),StringComparison.OrdinalIgnoreCase)&&File.Exists(target)) File.Delete(target); } return Task.CompletedTask; }
}
